'use strict';

// MODULES //

var isFloat64Array = require( '@stdlib/assert/is-float64array' );
var isInteger = require( '@stdlib/assert/is-integer' ).isPrimitive;
var isNonNegativeInteger = require( '@stdlib/assert/is-nonnegative-integer' ).isPrimitive;
var min = require( '@stdlib/math/base/special/min' );
var max = require( '@stdlib/math/base/special/max' );


// MAIN //

/**
* Validates indexed input and workspace storage.
*
* @private
* @param {integer} norm - normalized norm
* @param {NonNegativeInteger} M - number of rows
* @param {NonNegativeInteger} N - number of columns
* @param {Float64Array} A - matrix
* @param {integer} sa1 - row stride
* @param {integer} sa2 - column stride
* @param {NonNegativeInteger} oa - matrix offset
* @param {Float64Array} work - scratch storage
* @param {integer} sw - workspace stride
* @param {NonNegativeInteger} ow - workspace offset
* @throws {TypeError} invalid storage
* @throws {RangeError} insufficient indexed elements
* @returns {void}
*/
function validate( norm, M, N, A, sa1, sa2, oa, work, sw, ow ) {
	var lo;
	var hi;
	var a;
	var b;

	if ( M === 0 || N === 0 ) {
		return;
	}
	if ( !isFloat64Array( A ) ) {
		throw new TypeError( 'invalid argument. Matrix must be a Float64Array.' );
	}
	if (
		!isInteger( sa1 ) ||
		!isInteger( sa2 ) ||
		!isNonNegativeInteger( oa )
	) {
		throw new RangeError( 'invalid argument. Matrix strides must be integers and its offset must be a nonnegative integer.' );
	}
	a = (M-1)*sa1;
	b = (N-1)*sa2;
	lo = oa + min( 0, a ) + min( 0, b );
	hi = oa + max( 0, a ) + max( 0, b );
	if ( lo < 0 || hi >= A.length ) {
		throw new RangeError( 'invalid argument. Matrix has insufficient indexed elements.' );
	}
	if ( norm !== 73 ) {
		return;
	}
	if ( !isFloat64Array( work ) ) {
		throw new TypeError( 'invalid argument. Workspace must be a Float64Array.' );
	}
	if ( !isInteger( sw ) || sw === 0 || !isNonNegativeInteger( ow ) ) {
		throw new RangeError( 'invalid argument. Workspace stride must be a nonzero integer and its offset must be a nonnegative integer.' );
	}
	a = (M-1)*sw;
	if ( ow + min( 0, a ) < 0 || ow + max( 0, a ) >= work.length ) {
		throw new RangeError( 'invalid argument. Workspace has insufficient indexed elements.' );
	}
}


// EXPORTS //

module.exports = validate;
